package br.com.orbe.dao.jdbc;
import br.com.orbe.config.ConnectionFactory;import br.com.orbe.dto.UsuarioAdministrativoItem;import br.com.orbe.model.enums.*;import java.sql.SQLException;import java.util.*;
public class UsuarioAdministrativoDaoJdbc extends AbstractJdbcDao{
 public UsuarioAdministrativoDaoJdbc(ConnectionFactory f){super(f);}public List<UsuarioAdministrativoItem>listar(){String sql="SELECT u.usuario_id,u.nome,u.cpf,u.email,u.telefone,u.data_nascimento,u.status,u.ultimo_acesso_em,p.perfil,p.matricula FROM usuario u JOIN usuario_perfil p ON p.usuario_id=u.usuario_id AND p.ativo=TRUE ORDER BY u.nome";List<UsuarioAdministrativoItem>x=new ArrayList<>();try(var c=connectionFactory.open();var s=c.prepareStatement(sql);var r=s.executeQuery()){while(r.next()){var i=new UsuarioAdministrativoItem();i.setId(r.getLong("usuario_id"));i.setNome(r.getString("nome"));i.setCpf(r.getString("cpf"));i.setEmail(r.getString("email"));i.setTelefone(r.getString("telefone"));i.setDataNascimento(r.getObject("data_nascimento",java.time.LocalDate.class));i.setStatus(StatusUsuario.valueOf(r.getString("status")));i.setPerfil(PerfilUsuario.valueOf(r.getString("perfil")));i.setMatricula(r.getString("matricula"));var a=r.getTimestamp("ultimo_acesso_em");i.setUltimoAcessoEm(a==null?null:a.toLocalDateTime());x.add(i);}return x;}catch(SQLException e){throw persistenceException(e);}}
}
